/**  Result of a commit attempt. `committed: false` means the tree was clean. */
export type CommitOutcome = {
	committed: boolean,
	sha: string | null,
	/**
	 *  Commits the local branch is ahead of the last-fetched remote (no
	 *  network).
	 */
	ahead: number,
	skippedLargeFiles: SkippedFile[],
};

/**
 *  One matched contact, flattened to the fields Reflect can write into a
 *  note as markdown. Photos are deliberately absent (out of v1 scope).
 */
export type ContactMatch = {
	/**
	 *  Locale-aware display name from `CNContactFormatter` (given/family
	 *  ordering differs by locale, so it is not composed by hand).
	 */
	fullName: string,
	givenName: string,
	familyName: string,
	emails: string[],
	phones: string[],
};

/**  The Contacts permission state, as the settings UI consumes it. */
export type ContactsAuthorization = 
/**  The user has not been asked yet — enabling the toggle should prompt. */
"notDetermined" | 
/**
 *  Access is blocked by policy (parental controls, MDM); the user cannot
 *  grant it from the app.
 */
"restricted" | 
/**  The user said no — point them at System Settings. */
"denied" | 
/**  Full access granted. */
"authorized" | 
/**  Partial access (iOS 18+); reads work against the shared subset. */
"limited" | 
/**  No Contacts framework on this platform. */
"unavailable";

/**  The directories and user agent the iOS shell starts the core with. */
export type CoreStartConfig = {
	appDataDir: string | null,
	documentDir: string | null,
	userAgent: string | null,
};

/**
 *  Byte counts for an active model download. Absent until the download
 *  starts (cache probing, or a cached model that skips downloading); after
 *  the last byte it stays at 100% through the model-load phase.
 */
export type EmbedProgress = {
	downloaded: number,
	total: number,
};

export type EmbedStatus = 
/**  No model loaded yet; `embed_ensure` will download/load it. */
{ status: "uninitialized" } | 
/**
 *  Download/load in progress (first run downloads ~90MB). The runtime
 *  keeps the latest byte counts, so polls and `embed:status` events
 *  report the same progress.
 */
{ status: "loading"; progress?: EmbedProgress | undefined } | 
/**  `embed_texts` is ready; `model` is recorded per vector (rebuild key). */
{ status: "ready"; model: string } | 
/**  Load failed; semantic search is unavailable (lexical still works). */
{ status: "failed"; message: string } | 
/**  This platform or CPU has no embedding runtime. */
{ status: "unsupported" };

/**
 *  One chunk of a note, built in TS (`@reflect/core` chunker). `vector` is
 *  present only for new/changed chunks — `None` means "this chunk's hash
 *  already has a row; keep its vector, refresh its metadata" (positions and
 *  headings shift when text moves above an unchanged chunk).
 */
export type EmbeddedChunk = {
	heading: string | null,
	posFrom: number,
	posTo: number,
	text: string,
	contentHash: string,
	modelId: string,
	vector: number[] | null,
};

/**
 *  An event the native side broadcasts. The serde name is the wire name, and
 *  `pnpm gen:types` exports it to TypeScript and Swift.
 */
export type EventName = 
/**  Batched [`crate::FileChange`]s for files that changed outside the editor. */
"index:changed" | 
/**  Asks the frontend for one full reconcile pass. Carries no payload. */
"index:reconcile" | 
/**
 *  Fired after a note-projection write commits. Secondary note windows run
 *  no indexer of their own and refetch their index-backed queries on this
 *  signal.
 */
"index:written" | 
/**
 *  Fired after a note's rows move to a new path (an in-app rename or an
 *  id-healed external one), with `{ "from": ..., "to": ... }`.
 */
"note:moved";

/**  One changed graph file. */
export type FileChange = {
	/**  Graph-relative path, forward-slashed. */
	path: string,
	kind: ChangeKind,
	/**
	 *  Last-modified time in epoch milliseconds, set for upserts. The frontend
	 *  stamps `notes.mtime` from this — without it, watcher-indexed rows would
	 *  carry no real timestamp (and reconcile would never repair them, since it
	 *  is content-hash gated).
	 */
	modifiedMs?: number | undefined,
};

/**  Metadata for a file inside the graph. */
export type FileMeta = {
	/**  Graph-relative path, forward-slashed. */
	path: string,
	size: number,
	/**  Last-modified time in epoch milliseconds. */
	modifiedMs: number,
	/**
	 *  True when the file is iCloud-evicted: the note exists but its content
	 *  is not on disk until re-downloaded. Consumers must not read it — a
	 *  read blocks on an on-demand download — and must not treat it as
	 *  deleted (Plan 21). Covers both eviction forms: for a legacy `.icloud`
	 *  stub, `size` and `modified_ms` describe the stub; for a modern
	 *  dataless file they are the real (preserved) values.
	 */
	placeholder?: boolean | undefined,
};

/**  A command of the page's formatting toolbar. */
export type FormattingCommand = "slash" | "list" | "todo" | "link" | "tag" | "dedent" | "indent" | "up" | "down" | "dismiss";

/**
 *  An HTTPS sign-in supplied per call. Which username and secret a host
 *  wants is `@reflect/core`'s business (GitHub: `x-access-token` plus the
 *  managed token); this layer only presents it, once, as basic auth, and
 *  only to `origin`, the scheme, host and port it was stored for.
 * 
 *  No `Debug`: a derived one would print `secret`.
 */
export type GitCredential = {
	origin: string,
	username: string,
	secret: string,
};

/**
 *  Snapshot of the graph's backup repository for the UI and the sync engine.
 *  Deliberately cheap — refs and config only, no working-tree scan.
 */
export type GitStatus = {
	/**  Whether the graph has a repository at all (backup set up). */
	initialized: boolean,
	branch: string | null,
	remoteUrl: string | null,
	/**  Commits ahead/behind the last-fetched remote branch (no network). */
	ahead: number,
	behind: number,
};

/**
 *  Progress of the running import, emitted to the frontend as
 *  `import:progress` events.
 */
export type GraphImportProgress = {
	stage: GraphImportStage,
	done: number,
	total: number,
};

/**  Which phase of the import a progress tick belongs to. */
export type GraphImportStage = 
/**  Long remote downloads first. */
"downloading" | 
/**  Then fast local writes. */
"writing";

/**  Summary returned to the settings UI after an import completes. */
export type GraphImportSummary = {
	/**  Zip files newly written to the open graph. */
	importedFiles: number,
	/**  Zip files already present with identical bytes, left untouched. */
	skippedFiles: number,
	/**
	 *  Remote attachments now stored locally under `assets/` (whether newly
	 *  written or already present from an earlier import).
	 */
	downloadedAssets: number,
	/**
	 *  Remote attachments that are permanently gone (4xx); their notes keep
	 *  the remote link.
	 */
	failedAssetDownloads: number,
	/**
	 *  Zip files written under a `-2`-style suffixed name because their own
	 *  name is held by a differing existing file — a genuine same-name file,
	 *  or one the filesystem merely aliases to the same path
	 *  (case-insensitive APFS folds `Füße.md`/`füsse.md`/`füße.md` together;
	 *  the V1 export keeps them distinct notes). Renamed assets have the
	 *  imported notes' `assets/…` links rewritten to the suffixed name.
	 */
	renamedFiles: number,
	/**
	 *  Existing daily notes that gained the imported entry's body: the day
	 *  already had a note with different content, so the import appends
	 *  rather than duplicating the day under a suffixed name.
	 */
	mergedFiles: number,
	/**
	 *  Graph-relative paths written to the open graph (new files and merged
	 *  daily notes).
	 */
	changedPaths: string[],
};

/**  Identity of an open graph, returned to the frontend. */
export type GraphInfo = {
	/**  Absolute path of the graph root. */
	root: string,
	/**  Display name (the root folder name). */
	name: string,
	/**
	 *  Open-session generation, bumped on every graph open. Mutating file
	 *  commands echo it back and are rejected when stale, so a write enqueued
	 *  for one graph can never land in another graph's same-named file.
	 */
	generation: number,
};

/**  The direction of a move in the history. */
export type HistoryDirection = "back" | "forward";

/**  Whether the history can move back and forward. */
export type HistoryState = {
	back: boolean,
	forward: boolean,
};

/**  `host.log` arguments: one line of the web app. */
export type HostLogArgs = {
	level: HostLogLevel,
	message: string,
};

/**  The severity of a `host.log` line. */
export type HostLogLevel = "error" | "warn" | "info";

/**  `host.open_url` arguments. */
export type HostOpenUrlArgs = {
	/**  An absolute URL. */
	url: string,
};

/**  One store product. */
export type IapProduct = {
	productId: string,
	/**  The store-localized display price, such as `$4.99`. */
	formattedPrice?: string | null | undefined,
};

/**  `plugin:iap|purchase` and `plugin:iap|get_product_status` arguments. */
export type IapProductArgs = {
	payload: IapProductQuery,
};

/**  One product. */
export type IapProductQuery = {
	productId: string,
	productType: IapProductType,
};

/**  `plugin:iap|get_product_status` result. */
export type IapProductStatus = {
	/**  Whether a verified transaction entitles the user to the product now. */
	isOwned: boolean,
};

/**  The kind of store product. */
export type IapProductType = 
/**  An auto-renewable subscription. */
"subs";

/**  `plugin:iap|get_products` result. */
export type IapProducts = {
	products: IapProduct[],
};

/**  `plugin:iap|get_products` arguments. */
export type IapProductsArgs = {
	payload: IapProductsQuery,
};

/**  The products to look up. */
export type IapProductsQuery = {
	productIds: string[],
	productType: IapProductType,
};

/**  iCloud availability as desktop onboarding and settings consume it. */
export type IcloudStatus = {
	/**
	 *  True when the app can reach its iCloud Drive container (entitled
	 *  build, signed-in account). Dev builds without the provisioning
	 *  profile honestly report `false`.
	 */
	available: boolean,
	/**  The container's `Documents/` directory when available. */
	documentsRoot: string | null,
	/**
	 *  Every existing graph inside the container (name-sorted) — the
	 *  returning-user fast path: onboarding lists them to open alongside
	 *  creating a fresh one. Same rule as every container path: derive
	 *  fresh, never persist.
	 */
	existingGraphRoots: string[],
};

/**  What one sweep did. */
export type IcloudSweepOutcome = {
	/**  Every file the sweep changed on disk — reindex these directly. */
	changed: FileChange[],
	/**  Graph-relative paths of the conflict copies the sweep wrote. */
	copies: string[],
	/**  Conflicts resolved without user interaction. */
	autoResolved: number,
};

/**
 *  One `touch` entry: re-stamp `path`'s stored mtime to `mtime` (epoch ms, as
 *  listed by the file walk).
 */
export type IndexTouch = {
	path: string,
	mtime: number,
};

export type IndexedAlias = {
	alias: string,
	aliasKey: string,
};

export type IndexedClaim = {
	/**  Folded spelling this note answers to. */
	key: string,
	/**  One of the `claim_tier` constants in `reflect-index` (`CLAIM_TIER` in TS). */
	tier: number,
};

export type IndexedEmail = {
	/**  Display casing (as written in the field bullet). */
	email: string,
	/**  Case-folded match key: what resolution compares against. */
	emailKey: string,
};

export type IndexedLink = {
	kind: LinkKind,
	targetRaw: string,
	/**
	 *  Name key the link answers to: for wiki links, the folded name key
	 *  (empty when the target has no name reading: a rooted path, `#self`, or
	 *  a refused URI); for md links, the lowercased href.
	 */
	targetKey: string,
	/**  Folded vault path when the link names a file; None when it names a note. */
	targetPathKey: string | null,
	alias: string | null,
	posFrom: number,
	posTo: number,
};

/**
 *  A note's extracted projection, built in TS (Plan 03) and applied as one
 *  row-set. Mirrors the `indexedNoteSchema` zod contract in
 *  `packages/core/src/indexing/indexed-note.ts` field-for-field (serde
 *  `rename_all = "camelCase"` matches the camelCase payload); a change on either
 *  side must be mirrored on the other.
 */
export type IndexedNote = {
	path: string,
	id: string | null,
	title: string,
	titleKey: string,
	/**  ASCII-folded graph path: what a path-qualified link joins against. */
	pathKey: string,
	/**  Derived from the path; templates are excluded from note surfaces. */
	kind: NoteKind,
	dailyDate: string | null,
	isPrivate: boolean,
	isPinned: boolean,
	/**  Explicit pin order (`pinned: <n>`); None for bare `pinned: true`. */
	pinnedOrder: number | null,
	/**  The note is not blank: it has display text, or a body the FTS can match. */
	hasContent: boolean,
	/**  The published GitHub Gist's html url, when the note has one. */
	gistUrl: string | null,
	/**  The body changed since it was last published to the gist. */
	gistStale: boolean,
	fileHash: string,
	mtime: number,
	text: string,
	/**
	 *  Description text of referenced assets (Plan 20), folded into the FTS
	 *  `body` only — never `preview` or anything AI-reachable.
	 */
	assetText?: string | undefined,
	/**  The All Notes row snippet, derived once here rather than per query. */
	preview: string,
	links: IndexedLink[],
	tags: IndexedTag[],
	aliases: IndexedAlias[],
	/**  Every folded spelling this note answers to (see `note_claims`). */
	claims: IndexedClaim[],
	/**  Emails the note owns via `- Email:` contact-field bullets. */
	emails: IndexedEmail[],
	assets: string[],
	/**  Task rows for the Tasks projection (Plan 18). */
	tasks: IndexedTask[],
};

export type IndexedTag = {
	/**  Display casing (first-seen in the document). */
	tag: string,
	/**  Case-folded match key: what queries compare against. */
	tagKey: string,
};

/**
 *  One round task (Plan 18). `ast_path` is the task's address in the note
 *  body's block AST (a JSON array of child indexes) and, with `note_path`, the
 *  row's primary key.
 */
export type IndexedTask = {
	astPath: string,
	/**  The task's first paragraph as Markdown, marker excluded. */
	markdown: string,
	/**
	 *  The headings above the task, then its ancestor list items' first
	 *  paragraphs, as Markdown, outermost first.
	 */
	breadcrumbs?: string[] | undefined,
	checked: boolean,
	/**  Explicit due date (first `[[YYYY-MM-DD]]` in the item), or None. */
	dueDate: string | null,
};

/**  A file the user picked, for the editor to attach. */
export type IntentFile = {
	name: string,
	/**  The MIME type. */
	type: string,
	/**  The bytes, base64. */
	data: string,
};

/**  A captured web page. */
export type LinkCaptureEnvelope = {
	/**  Always 1. */
	version: number,
	/**  A UUID; it names the spool files. */
	id: string,
	url: string,
	title: string,
	selection?: string | null | undefined,
	contentText?: string | null | undefined,
	/**  In-page meta description; only the iOS share extension sets it. */
	metaDescription?: string | null | undefined,
	note?: string | null | undefined,
	/**
	 *  The screenshot file beside the envelope. The spooler sets it; the
	 *  extension never sends it.
	 */
	screenshotRef?: string | null | undefined,
	/**  ISO-8601 with an offset. */
	capturedAt: string,
	source: CaptureSource,
};

/**  The syntax of a link: `[[wiki]]` or `[md](path)`. */
export type LinkKind = "wiki" | "md";

export type LinkPreviewHtml = {
	html: string,
	finalUrl: string,
};

/**
 *  How a local note read (the desktop `note_read_local` command) found the
 *  note on disk.
 */
export type LocalNoteRead = 
/**  The bytes are local; here they are. */
{ kind: "content"; content: string } | 
/**
 *  The note is iCloud-evicted (a dataless file, or an `.icloud` stub in
 *  the logical path's place). Reading it would block on an on-demand
 *  download — this command refuses instead.
 */
{ kind: "evicted" };

/**
 *  A confirmation the shell shows before it sends the item's intent: an
 *  action sheet (a popover on iPad) with one destructive button and Cancel.
 */
export type MenuConfirm = {
	title: string,
	message?: string | null | undefined,
	/**  The label of the destructive button. */
	action: string,
};

/**
 *  One row of a menu, or a section of rows, in the order the shell shows
 *  them.
 */
export type MenuItem = 
/**  One row. specta-swift names its payload `MenuItemActionData`. */
{ type: "action"; id: string; title: string; 
/**  An SF Symbol name. */
icon?: string | null | undefined; destructive?: boolean | null | undefined; disabled?: boolean | null | undefined; 
/**  Shows a checkmark. */
checked?: boolean | null | undefined; confirm?: MenuConfirm | null | undefined } | { type: "section"; title?: string | null | undefined; items: MenuItem[] };

export type MergeKind = "upToDate" | "fastForward" | "merged";

/**
 *  The storage locations available to the mobile graph, as the onboarding
 *  screen and `GraphProvider` consume them.
 */
export type MobileStorageInfo = {
	/**
	 *  The app-sandbox `Documents/` directory — always available, never
	 *  synced. iOS container paths embed a UUID that changes across
	 *  restore/update, so callers must never persist this absolute path.
	 */
	localRoot: string,
	/**
	 *  The container's `Documents/` directory when iCloud Drive is usable
	 *  (entitled build + signed-in account) — where a new graph directory
	 *  is created. `None` when signed out or the platform has no iCloud.
	 *  Same rule as `local_root`: derive fresh, never persist.
	 */
	icloudDocumentsRoot: string | null,
	/**
	 *  Every existing graph directory inside the container (name-sorted,
	 *  same listing as desktop's `icloud_status`) — onboarding and the
	 *  graph switcher list them. Best-effort: content still syncing down at
	 *  first launch can grow this later. The persisted selector is the
	 *  graph's *name*, never these absolute paths.
	 */
	icloudGraphRoots: string[],
};

/**
 *  Path-derived addressing for a moved row: the folded destination path plus
 *  the claims that derive from it. Folded in TypeScript — Rust never folds.
 */
export type MovedNoteAddress = {
	pathKey: string,
	basenameKey: string,
	/**  Set only for a calendar-valid `daily/YYYY-MM-DD.md` destination. */
	dailyDate: string | null,
};

/**  The arguments of a command that takes none. */
export type NoArgs = Record<string, never>;

/**  Result of claiming a note path without overwriting an existing file. */
export type NoteCreateOutcome = 
/**  The path was free and now contains the supplied bytes. */
{ kind: "created"; modifiedMs: number | null } | 
/**  A file or iCloud eviction placeholder already owns the path. */
{ kind: "collision" };

/**  What a note file is, from its path. */
export type NoteKind = "daily" | "note" | "template";

/**
 *  One user-initiated move, with the folded addressing for both directions:
 *  the destination's for the forward row move, the source's for the
 *  compensating reverse move when the disk refuses.
 */
export type NoteMoveRequest = {
	from: string,
	to: string,
	toAddress: MovedNoteAddress,
	fromAddress: MovedNoteAddress,
};

/**  What a note write left on disk. */
export type NoteWriteOutcome = {
	/**  The note's on-disk mtime (epoch ms) after the call. */
	modifiedMs: number | null,
	/**
	 *  The full note text now on disk, when the note had moved past the
	 *  expected revision and the file holds something other than `contents`.
	 */
	merged: string | null,
};

/**  A pinned note in the iPad sidebar. */
export type PinnedNote = {
	path: string,
	/**  The name the sidebar shows. */
	title: string,
};

/**  A tap on the `+` (`tap`) or on one item of the capture menu. */
export type PlusCommand = "tap" | "note" | "task" | "audio";

/**  The `+` of a screen: Daily's capture menu, or one action. */
export type PlusState = 
/**
 *  The capture menu. `audio` is the audio memo phase, or none where the
 *  recorder is unavailable: the menu then has no audio item.
 */
{ kind: "capture"; audio: AudioPhase | null } | 
/**  One action. `label` is the accessibility label. */
{ kind: "action"; label: string };

/**
 *  What one pull did: the commit of local changes, then the merge of the
 *  fetched remote branch.
 */
export type PullOutcome = {
	/**  Whether local changes were committed before the merge. */
	committed: boolean,
	/**
	 *  Commits the local branch is ahead of the last-fetched remote after the
	 *  merge (no network).
	 */
	ahead: number,
	skippedLargeFiles: SkippedFile[],
	kind: MergeKind,
	/**  Graph-relative paths of the conflict copies the merge wrote. */
	reviewPaths: string[],
	/**  Every file the merge changed on disk. */
	changedFiles: ChangedFile[],
};

/**
 *  Result of a push attempt. `pushed: false` with `non_fast_forward: true` is
 *  the normal two-device case (pull, merge, retry); a `rejection_message`
 *  carries anything else the remote said (e.g. GitHub push protection).
 */
export type PushOutcome = {
	pushed: boolean,
	/**  Auth and network failures are `AppError`s, never this. */
	nonFastForward: boolean,
	rejectionMessage: string | null,
};

/**
 *  The quick note defaults the app mirrors into the App Group container
 *  for the iOS App Intent.
 */
export type QuickNoteDefaultsFile = {
	/**  Always 1. */
	version: number,
	/**  The bullet new entries nest under. */
	parent: string,
};

/**  A previously-opened graph, newest first in the stored list. */
export type RecentGraph = {
	root: string,
	name: string,
	openedMs: number,
};

/**  The reconcile delta: what changed on disk relative to the index. */
export type ReconcileScan = {
	/**  Markdown files listed (eviction placeholders included). */
	total: number,
	candidates: ScanCandidate[],
	orphans: ScanOrphan[],
	/**
	 *  Evicted files whose **content the index lacks**: no stored row (never
	 *  indexed on this device), or a listed mtime differing from the stored
	 *  row (a remote edit that synced while the file was evicted). The
	 *  reconcile cannot read these — placeholders are never candidates — so
	 *  it surfaces them for a *targeted* download request
	 *  (`icloud_request_downloads`); the materialized file then arrives as an
	 *  ordinary watcher upsert. Evicted files whose row is current are
	 *  deliberately absent: re-downloading content we already indexed would
	 *  fight the OS's eviction choice (Optimize Mac Storage). For legacy
	 *  `.icloud` stubs the listed mtime is the stub's own, so an
	 *  evicted-after-indexing note re-requests on each reconcile — matching
	 *  mobile's existing download-all-pending-notes behavior on open/resume.
	 */
	stalePlaceholders: string[],
};

/**  `plugin:recording|delete_staged` arguments. */
export type RecordingDeleteStagedArgs = {
	request: StagedRecordingPath,
};

/**
 *  `plugin:recording:recordingLevel`, about 10 times a second while
 *  recording in the foreground.
 */
export type RecordingLevelEvent = {
	/**  Linear input level from 0 to 1. */
	level: number,
	/**  Recorded time so far, pauses excluded. */
	elapsedMs: number,
};

/**
 *  `plugin:recording:nativeAction`: an OS entry point asked for something
 *  only the web view can present.
 */
export type RecordingNativeActionEvent = {
	/**  Currently only `recordAudio`. */
	action: string,
};

/**
 *  `plugin:recording:recordingSegment`: a finished segment of a session that
 *  still records. The final segment arrives in the stop result or in
 *  `recordingStopped`.
 */
export type RecordingSegmentEvent = {
	path: string,
	sessionStartedMs: number,
	part: number,
};

/**  The identity every segment of a session shares. */
export type RecordingSessionStart = {
	/**  Epoch milliseconds. */
	sessionStartedMs: number,
};

/**  `plugin:recording|start_recording` arguments. */
export type RecordingStartArgs = {
	request: StartRecordingOptions,
};

/**  Whether a session runs, and its recorded length so far. */
export type RecordingStatus = {
	recording: boolean,
	/**  Across every segment of the session. */
	elapsedMs: number,
};

/**  A session's final segment, still in staging. */
export type RecordingStopResponse = {
	/**  Absolute path of the staged `.m4a`, already `-end`-marked. */
	path: string,
	sessionStartedMs: number,
	/**  1-based position of this final segment. */
	part: number,
	/**  The whole session's recorded length. */
	durationMs: number,
};

/**  `plugin:recording:recordingStopped`: the shell ended a session. */
export type RecordingStoppedEvent = {
	path: string,
	sessionStartedMs: number,
	part: number,
	/**  The whole session's recorded length. */
	durationMs: number,
	reason: string,
};

/**
 *  Where the local branch stands relative to its last-fetched remote
 *  counterpart (no network — call after `fetch`).
 */
export type RemoteDelta = {
	ahead: number,
	behind: number,
};

/**
 *  Where the remote says the current branch is, next to the last-fetched
 *  tracking ref. `remote_oid` is `None` when the remote has no such branch;
 *  `default_branch` is the branch the remote's HEAD points at, `None` when
 *  the remote is empty.
 */
export type RemoteTip = {
	remoteOid: string | null,
	trackingOid: string | null,
	defaultBranch: string | null,
};

/**
 *  One file the TS reconcile must read: its listed mtime doesn't match the
 *  stored row (or is too fresh to trust), or it has no row at all. Stored
 *  facts ride along so the reconcile needs no follow-up query — a `None`
 *  hash marks an arrival (move-healing candidate).
 */
export type ScanCandidate = {
	path: string,
	/**  The file's listed on-disk mtime (epoch ms). */
	modifiedMs: number,
	/**  The stored row's mtime, or `None` when the path has no row. */
	storedMtime: number | null,
	/**  The stored row's content hash, or `None` when the path has no row. */
	storedHash: string | null,
};

/**
 *  A stored row whose file vanished from disk. Facts ride along because
 *  id-based move healing pairs orphans with arrivals and, on a heal, the
 *  moved row's hash decides whether the new path needs a re-index at all.
 */
export type ScanOrphan = {
	path: string,
	storedMtime: number,
	storedHash: string,
};

/**  A tap in the iPad sidebar. */
export type SidebarIntent = { kind: "chat" } | { kind: "search" } | { kind: "settings" } | 
/**  Opens a pinned note. */
{ kind: "openNote"; path: string } | { kind: "unpin"; path: string } | { kind: "share"; path: string } | 
/**  An item of the graph menu. */
{ kind: "menu"; id: string };

/**  What the iPad sidebar shows. */
export type SidebarState = {
	/**
	 *  The row to select: a tab, `chat`, or a pinned note's path after
	 *  `pinned:`.
	 */
	selection: string,
	/**  The pinned notes, in shelf order. */
	pinned: PinnedNote[],
	graphName: string,
	/**  The graph's color as `#rrggbb`, or none for the app's tint. */
	graphColor: string | null,
	/**  The menu of the graph button. */
	graphMenu: MenuItem[],
};

/**
 *  A file whose changes were withheld because it is at or above the size
 *  guardrail. An unchanged oversized file is not reported.
 */
export type SkippedFile = {
	/**  Graph-relative path (forward-slashed) of the withheld file. */
	path: string,
	size: number,
};

/**  One staged segment file. */
export type StagedRecordingFile = {
	/**  Absolute path of the staged `.m4a`. */
	path: string,
	sessionStartedMs: number,
	/**  1-based position within the session. */
	part: number,
	/**  True for the final segment of a session. */
	end: boolean,
	modifiedMs: number,
};

/**  `plugin:recording|list_staged` result. */
export type StagedRecordingList = {
	files: StagedRecordingFile[],
};

/**  One staged segment file, by its absolute path. */
export type StagedRecordingPath = {
	path: string,
};

/**  How a recording session runs. */
export type StartRecordingOptions = {
	/**
	 *  Rotate the recorder after this much audio, natively, so rotation holds
	 *  even if JS never wakes. Each segment is one staged file.
	 */
	segmentMs: number,
	/**
	 *  Remind the user this often while the session runs. The shell schedules
	 *  the notification itself, so it survives a sleeping web view and is
	 *  cleared by whatever ends the session.
	 */
	reminderMs: number,
};

/**  How much of the graph a sweep checks for unresolved versions. */
export type SweepScope = 
/**
 *  Check every note, and run the store-housekeeping passes. Used on
 *  resume, adoption baseline, and any sweep without a live watch.
 */
"full" | 
/**
 *  Restrict the per-note `NSFileVersion` checks to the paths the live
 *  metadata query flags as conflicted
 *  (`reflect_core::icloud::watch::conflicted_paths`). Each check is a
 *  synchronous round-trip to `fileproviderd`. Mobile's signal and arrival
 *  sweeps. Degrades to `Full` whenever the watch cannot answer completely.
 */
"candidates" | 
/**
 *  Restrict the version checks to this sweep's `ingested_paths`. Desktop's
 *  arrival sweeps: no metadata watch runs there (see
 *  `reflect_core::icloud::watch`). A conflict version that never touches the
 *  working file is the `Full` sweep's job.
 */
"ingested";

/**
 *  Captured text: one folded line the drain writes into the capture day's
 *  daily note.
 */
export type TextCaptureEnvelope = {
	/**  Always 1. */
	version: number,
	/**  A UUID; it names the spool file. */
	id: string,
	kind: TextCaptureKind,
	text: string,
	/**  The top-level bullet the entry nests under; none appends at the end. */
	parent?: string | null | undefined,
	/**  ISO-8601 with an offset. */
	capturedAt: string,
	source: TextCaptureSource,
};

/**  Where a text capture lands in the daily note. */
export type TextCaptureKind = "append" | "checkbox" | "task";

/**  Who produced a text capture. */
export type TextCaptureSource = "deep-link" | "ios-share" | "ios-intent";

/**  The formatting toolbar of the focused editor. */
export type ToolbarState = {
	canIndent: boolean,
	canDedent: boolean,
	canMoveUp: boolean,
	canMoveDown: boolean,
	canAttachFiles: boolean,
};

/**  The phase of a web push or pop slide. */
export type TransitionPhase = "start" | "end";

export type Value = null | boolean | number | string | unknown[] | { [key in string]: unknown };

/**
 *  Counts from the vault catalog. `skipped` is what the walk refused or
 *  failed to list (unreadable directories, symlinks, default-pruned trees) —
 *  the number that keeps "why isn't my file showing up" diagnosable.
 */
export type VaultScanStats = {
	notes: number,
	attachments: number,
	skipped: number,
};

/**  `plugin:web-auth|start` result. */
export type WebAuthCallback = {
	/**  The callback URL; none when the user cancels. */
	url?: string | null | undefined,
};

/**  A system web sign-in. */
export type WebAuthOptions = {
	/**  The page that starts the sign-in. */
	url: string,
	/**  The URL scheme that ends the sign-in. */
	callbackScheme: string,
	/**
	 *  When true, the session shares no cookies or website data with the
	 *  system browser.
	 */
	ephemeral: boolean,
};

/**  `plugin:web-auth|start` arguments. */
export type WebAuthStartArgs = {
	payload: WebAuthOptions,
};

/**
 *  What a secondary window needs to boot: the open graph's identity (both
 *  session generations, unbumped) and the deep link it was created to show.
 */
export type WindowBootstrap = {
	graph: GraphInfo,
	/**
	 *  The open index session's generation, or null when the main window's
	 *  index failed to open (the note window then boots without index reads).
	 */
	indexGeneration: number | null,
	/**
	 *  The `reflect://` link this window was opened for — one-shot, absent on
	 *  a reload (the router simply stays where the reloaded window was).
	 */
	initialDeepLink: string | null,
};
